import java.util.*;import java.math.BigInteger;
public class RSA {public static void main(String[]z){Scanner sc=new Scanner(System.in);System.out.print("Enter the first prime: ");BigInteger p=sc.nextBigInteger();System.out.print("Enter the second prime: ");BigInteger q=sc.nextBigInteger();if(!p.isProbablePrime(50)||!q.isProbablePrime(50)||p.equals(q)){System.out.println("Enter two distinct prime numbers.");return;}BigInteger n=p.multiply(q),phi=p.subtract(BigInteger.ONE).multiply(q.subtract(BigInteger.ONE));BigInteger e=BigInteger.valueOf(65537);if(e.compareTo(phi)>=0||!e.gcd(phi).equals(BigInteger.ONE)){e=BigInteger.valueOf(3);while(e.compareTo(phi)<0&&!e.gcd(phi).equals(BigInteger.ONE))e=e.add(BigInteger.TWO);}if(e.compareTo(phi)>=0){System.out.println("Unable to choose public exponent.");return;}BigInteger d=e.modInverse(phi);System.out.println("Public key (e, n): ("+e+", "+n+")");System.out.println("Private key (d, n): ("+d+", "+n+")");System.out.print("Enter message integer (0 <= m < n): ");BigInteger m=sc.nextBigInteger();if(m.signum()<0||m.compareTo(n)>=0){System.out.println("Message must be between 0 and n-1.");return;}BigInteger c=m.modPow(e,n),plain=c.modPow(d,n);System.out.println("Encrypted: "+c);System.out.println("Decrypted: "+plain);}}
